using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class R53LargeCompareTests
{
 [TestMethod]public Task TwentyFourAndFortyEightMpCompareColdWarmCancelAndRelease()=>RunSta(async()=>{
  var output=Environment.GetEnvironmentVariable("KITAO_R53_LARGE_COMPARE");if(output is null){Assert.Inconclusive("Explicit large output required");return;}EnsureTestApplication();Directory.CreateDirectory(output);var rows=new List<object>();
  foreach(var (w,h) in new[]{(6000,4000),(8000,6000)}){
   var requested=Environment.GetEnvironmentVariable("KITAO_R53_COMPARE_WIDTH");if(requested is not null&&requested!=w.ToString())continue;var root=Path.Combine(output,w.ToString());Directory.CreateDirectory(root);var path=Path.Combine(root,"synthetic-large.jpg");var bytes=new byte[w*h*3];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*3;bytes[i]=(byte)(x*220/w);bytes[i+1]=(byte)(y*220/h);bytes[i+2]=(byte)(40+(x+y)%150);}var bitmap=BitmapSource.Create(w,h,96,96,PixelFormats.Rgb24,null,bytes,w*3);StudioQuickExport.Encode(bitmap,path,path,StudioExportFormat.Jpeg);bytes=[];bitmap=null!;GC.Collect();GC.WaitForPendingFinalizers();
   using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root));await vm.LoadTargetAsync(path);var exposure=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure");for(int n=0;n<3;n++){vm.Editor.SetToolParameter(exposure,n*.3+.2);await vm.CreateR53VariantAsync(false);}var ids=vm.R53Variants.Take(4).Select(v=>v.Id).ToArray();var main=vm.R53MainVariantId;var selected=vm.ActiveTarget!.ActiveEditVersionId;GC.Collect();GC.WaitForPendingFinalizers();var process=Process.GetCurrentProcess();
   foreach(int count in new[]{2,3,4}){typeof(ReferenceColorWorkspaceViewModel).GetMethod("ClearR53CompareCache",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(vm,null);long peak=0;using var stop=new CancellationTokenSource();var sampler=Task.Run(async()=>{while(!stop.IsCancellationRequested){process.Refresh();peak=Math.Max(peak,process.WorkingSet64);try{await Task.Delay(5,stop.Token);}catch(OperationCanceledException){}}});process.Refresh();var startWorking=process.WorkingSet64;var allocation=GC.GetTotalAllocatedBytes(true);var watch=Stopwatch.StartNew();await vm.PrepareR53VariantComparisonAsync(ids.Take(count).ToArray());var cold=watch.Elapsed.TotalMilliseconds;watch.Restart();await vm.PrepareR53VariantComparisonAsync(ids.Take(count).ToArray());var warm=watch.Elapsed.TotalMilliseconds;stop.Cancel();await sampler;Assert.AreEqual(count,vm.R53CompareFrames.Count);Assert.IsTrue(vm.R53CompareFrames.All(f=>Math.Max(f.Image.PixelWidth,f.Image.PixelHeight)<=1200));Assert.AreEqual(main,vm.R53MainVariantId);Assert.AreEqual(selected,vm.ActiveTarget.ActiveEditVersionId);rows.Add(new{width=w,height=h,count,coldMs=cold,warmMs=warm,compareStartWorkingBytes=startWorking,compareSampledPeakWorkingBytes=peak,compareAllocatedBytes=GC.GetTotalAllocatedBytes(true)-allocation,peakWorkingSetBytes=Process.GetCurrentProcess().PeakWorkingSet64,managedBytes=GC.GetTotalMemory(false),decodedProxyEdge=1200,scope="Full workspace includes original loading; peak includes fixture generation and managed test setup, not product-only ceiling"});}
   var a=vm.PrepareR53VariantComparisonAsync(ids);vm.CloseR53VariantComparison();var b=vm.PrepareR53VariantComparisonAsync(ids.Take(2).ToArray());await Task.WhenAll(a,b);Assert.AreEqual(2,vm.R53CompareFrames.Count);vm.CloseR53VariantComparison();Assert.IsEmpty(vm.R53CompareFrames);vm.Dispose();GC.Collect();GC.WaitForPendingFinalizers();
  }File.WriteAllText(Path.Combine(output,"LARGE_COMPARE.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
 });
 sealed class Dialogs(string root):IDialogService{public IReadOnlyList<string> ChooseFiles(string a,string b,bool c)=>[];public string? ChooseFolder(string a,string? b=null)=>root;public string? ChooseSaveFile(string a,string b,string c,string? d=null)=>null;public bool Confirm(string a,string b)=>true;public void ShowInfo(string a){}public void ShowError(string a){}public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string> ids)=>ids;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RAWSelectionAssistant.Core.Models.RawFileEntry? ChooseRawCandidate(IReadOnlyList<RAWSelectionAssistant.Core.Models.RawFileEntry> x)=>null;public bool ShowMediaDetails(RAWSelectionAssistant.Core.Models.MediaSelectionItem x,bool y)=>false;public void RevealFile(string p){}}
